        Image.open(file_storage.stream).verify()
        file_storage.stream.seek(0)
        img = ImageOps.exif_transpose(Image.open(file_storage.stream)).convert("RGBA")
        img.thumbnail((800, 400), Image.Resampling.LANCZOS)
